  if (pot >= 500){
    digitalWrite(ledPwm, !digitalRead(ledPwm));	
    delay(100);    
  } 
}

void interrupcaoPino2() // Função de interrupção do pino2, é executado quando o botão do pino2 é pressionado
{                    
  digitalWrite(led, !digitalRead(led));
}
