```c
void inverterArray(int arr[], int tamanho) {
  for (int i = 0; i < tamanho / 2; i++) {
    int temp = arr[i];
    arr[i] = arr[tamanho - 1 - i];
    arr[tamanho - 1 - i] = temp;
  }
}

void setup() {
  int dados[5] = {1, 2, 3, 4, 5};
  inverterArray(dados, 5);
  for (int i = 0; i < 5; i++) {
    Serial.println(dados[i]);
  }
}
```

