estadosMotor estadoAtual = PARADO;

void setup() {
    pinMode(13, OUTPUT);
    Serial.begin(9600);
}

void loop() {
    switch (estadoAtual) {
        case PARADO:
            digitalWrite(13, LOW);
            Serial.println("Motor parado.");
            break;
        case FRENTE:
            digitalWrite(13, HIGH);
            Serial.println("Motor para frente.");
            break;
        case TRAS:
            digitalWrite(13, HIGH);
            Serial.println("Motor para trás.");
            break;
    }
    delay(1000);
}

